    if not np.isfinite(mean_d) or mean_d <= 0:
        mean_d = 1.0

    p = edge_n_used.astype(float, copy=True)
    p_eff = p / (1.0 + 0.35 * p)

    utils = []
    for i, j in edges:
        d = float(edge_distance[i, j])
        pe = float(p_eff[i, j])
        u = d / (1.0 + 0.8 * pe) if d > 0 else 0.0
        utils.append((u, i, j))

    utils.sort(key=lambda x: x[0], reverse=True)

    k = max(1, int(np.ceil(0.45 * len(utils))))
    k = min(k, len(utils))
    lambda_pen = 0.22 * mean_d

    inc = np.zeros_like(p)
    for rank, (_, i, j) in enumerate(utils[:k]):
        w = 1.0 + 0.5 * (1.0 - rank / max(1, k))
        inc[i, j] += w
        inc[j, i] += w
        edge_n_used[i, j] += 1
        edge_n_used[j, i] += 1

    updated = edge_distance + lambda_pen * (p_eff + inc)
    return updated

