def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    m = tour.size
    if n == 0 or m == 0:
        return edge_distance.astype(float).copy()

    updated = edge_distance.astype(float).copy()
    alt_dist = np.full(n, np.inf, dtype=float)

    for i in range(m):
        u = int(tour[i])
        if u < 0 or u >= n:
            continue
        prev = int(tour[(i - 1) % m])
        nxt = int(tour[(i + 1) % m])
        best = np.inf
        row = edge_distance[u]
        for j in range(n):
            if j == u or j == prev or j == nxt:
                continue
            d = row[j]
            if d < best:
                best = d
        alt_dist[u] = best

    raw = {}
    for i in range(m):
        u = int(tour[i])
        if u < 0 or u >= n:
            continue
        prev = int(tour[(i - 1) % m])
        nxt = int(tour[(i + 1) % m])
        if prev < 0 or prev >= n or nxt < 0 or nxt >= n:
            continue

        d_prev = float(edge_distance[u, prev])
        d_nxt = float(edge_distance[u, nxt])

        if d_prev >= d_nxt:
            v = prev
            wd = d_prev
        else:
            v = nxt
            wd = d_nxt

        if alt_dist[u] < np.inf and wd > alt_dist[u]:
            a, b = (u, v) if u < v else (v, u)
            cnt = float(edge_n_used[a, b])
            raw[(a, b)] = raw.get((a, b), 0.0) + (wd - alt_dist[u]) / (1.0 + cnt)

    if not raw:
        best_edge = None
        best_val = -1.0
        for i in range(m):
            u = int(tour[i])
            v = int(tour[(i + 1) % m])
            if u == v or u < 0 or v < 0 or u >= n or v >= n:
                continue
            a, b = (u, v) if u < v else (v, u)
            cnt = float(edge_n_used[a, b])
            val = float(edge_distance[u, v]) / (1.0 + cnt)
            if val > best_val:
                best_val = val
                best_edge = (a, b)
        if best_edge is not None:
            raw[best_edge] = best_val

    for (a, b), pen in raw.items():
        updated[a, b] += pen
        updated[b, a] += pen
        edge_n_used[a, b] += 1
        edge_n_used[b, a] = edge_n_used[a, b]

    return updated

