def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    if n <= 3:
        return edge_distance.copy()

    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    if tour.size != n:
        return edge_distance.copy()
    if tour.min() < 0 or tour.max() >= n or np.unique(tour).size != n:
        return edge_distance.copy()

    succ = np.empty(n, dtype=int)
    pred = np.empty(n, dtype=int)
    for i in range(n):
        u = tour[i]
        succ[u] = tour[(i + 1) % n]
        pred[u] = tour[(i - 1) % n]

    d = edge_distance.astype(float, copy=False)
    mask = ~np.eye(n, dtype=bool)
    mean_dist = float(d[mask].mean()) if n > 1 else 1.0
    if not np.isfinite(mean_dist) or mean_dist <= 0:
        mean_dist = 1.0

    moves = []
    for u in range(n):
        for v in range(u + 1, n):
            if v == succ[u] or u == succ[v]:
                continue

            duv = d[u, v]
            best_gain = np.inf
            best_a = best_b = -1

            a = succ[u]
            b = succ[v]
            if a != b:
                gain = duv + d[a, b] - d[u, a] - d[v, b]
                if gain < best_gain:
                    best_gain = gain
                    best_a, best_b = a, b

            a = pred[u]
            b = pred[v]
            if a != b:
                gain = duv + d[a, b] - d[u, a] - d[v, b]
                if gain < best_gain:
                    best_gain = gain
                    best_a, best_b = a, b

            if best_a != -1:
                moves.append((best_gain, u, v, best_a, best_b))

    if not moves:
        return edge_distance.copy()

    moves.sort(key=lambda x: x[0])
    k = max(1, int(0.15 * len(moves)))

    reward = np.zeros((n, n), dtype=float)
    for gain, u, v, a, b in moves[:k]:
        base = 0.6 * max(0.0, gain) + 0.2 * mean_dist
        reward[u, v] += base
        reward[v, u] += base
        reward[a, b] += base
        reward[b, a] += base

    updated = d.copy()
    for u in range(n):
        for v in range(u + 1, n):
            r = reward[u, v]
            if r <= 0:
                continue

            usage = edge_n_used[u, v]
            r = r / (1.0 + 0.2 * usage)
            cap = max(1.5 * d[u, v], mean_dist)
            if r > cap:
                r = cap

            updated[u, v] -= r
            updated[v, u] -= r
            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    updated = (updated + updated.T) / 2.0
    return updated

