def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    n = edge_distance.shape[0]
    updated = edge_distance.astype(float, copy=True)
    if n <= 1:
        return updated

    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    m = tour.size
    if m < 2:
        return updated

    neighbors = {i: set() for i in range(n)}
    for k in range(m):
        u = int(tour[k])
        v = int(tour[(k + 1) % m])
        if u == v:
            continue
        if 0 <= u < n and 0 <= v < n:
            neighbors[u].add(v)
            neighbors[v].add(u)

    best_alt = {}
    for u in range(n):
        best_w = -1
        best_d = np.inf
        for w in range(n):
            if w == u or w in neighbors.get(u, set()):
                continue
            dw = float(edge_distance[u, w])
            if dw < best_d:
                best_d = dw
                best_w = w
        best_alt[u] = (best_w, best_d)

    edges = []
    seen = set()
    for k in range(m):
        u = int(tour[k])
        v = int(tour[(k + 1) % m])
        if u == v:
            continue
        if not (0 <= u < n and 0 <= v < n):
            continue
        a, b = (u, v) if u < v else (v, u)
        if (a, b) not in seen:
            seen.add((a, b))
            edges.append((u, v))

    factor = 0.15
    for u, v in edges:
        d = float(edge_distance[u, v])
        if d <= 0:
            continue

        p = float(edge_n_used[u, v])
        inc_total = 0.0
        rewards = []

        w_u, d_u = best_alt.get(u, (-1, np.inf))
        if w_u != -1 and d > d_u:
            part = factor * (d - d_u) / (1.0 + p)
            inc_total += part
            rewards.append((u, w_u, 0.5 * part))

        w_v, d_v = best_alt.get(v, (-1, np.inf))
        if w_v != -1 and d > d_v:
            part = factor * (d - d_v) / (1.0 + p)
            inc_total += part
            rewards.append((v, w_v, 0.5 * part))

        if inc_total > 0.0:
            updated[u, v] += inc_total
            updated[v, u] += inc_total

            for a, b, amt in rewards:
                updated[a, b] -= amt
                updated[b, a] -= amt

            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    if np.min(edge_distance) >= 0:
        np.maximum(updated, 0.0, out=updated)

    return updated

