def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                          edge_n_used: np.ndarray) -> np.ndarray:
    """Modify the edge distance matrix to escape the current local optimum.

    Args:
        edge_distance:  n*n symmetric matrix of original pairwise distances
        local_opt_tour: length-n array of node indices forming the current
                        local-optimal tour
        edge_n_used:    n*n symmetric matrix counting how many times each
                        edge has been penalised in previous iterations
    Returns:
        updated_edge_distance: modified n*n distance matrix to be used in
                               the next local search
    """
    n = edge_distance.shape[0]
    if n <= 1:
        return edge_distance.copy()

    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    m = len(tour)
    if m <= 1:
        return edge_distance.copy()

    pos = edge_distance[edge_distance > 0]
    lam = 0.1 * float(np.median(pos)) if pos.size > 0 else 1.0
    if lam <= 0:
        lam = 1.0

    current = edge_distance + lam * edge_n_used

    edges = []
    seen = set()
    for i in range(m):
        u = int(tour[i])
        v = int(tour[(i + 1) % m])
        if u == v:
            continue
        a, b = (u, v) if u < v else (v, u)
        if (a, b) in seen:
            continue
        seen.add((a, b))
        edges.append((i, u, v))

    if not edges:
        return edge_distance.copy()

    E = len(edges)
    best_gain = np.full(E, -np.inf, dtype=float)

    for i in range(E):
        _, u, v = edges[i]
        for j in range(E):
            if i == j:
                continue
            _, x, y = edges[j]
            if u == x or u == y or v == x or v == y:
                continue

            g1 = current[u, v] + current[x, y] - current[u, x] - current[v, y]
            g2 = current[u, v] + current[x, y] - current[u, y] - current[v, x]
            g = g1 if g1 > g2 else g2

            if g > best_gain[i]:
                best_gain[i] = g

    valid = np.isfinite(best_gain)

    if not np.any(valid):
        dists = np.array([edge_distance[u, v] for _, u, v in edges])
        selected = [int(np.argmax(dists))]
    else:
        order = np.argsort(best_gain)[::-1]
        max_sel = max(1, min(5, E // 10 + 1))
        selected = []
        for idx in order:
            idx = int(idx)
            if not np.isfinite(best_gain[idx]):
                continue
            selected.append(idx)
            if len(selected) >= max_sel:
                break
        if not selected:
            selected = [int(np.argmax(np.where(valid, best_gain, -np.inf)))]

    for idx in selected:
        _, u, v = edges[idx]
        bg = best_gain[idx]

        if np.isfinite(bg) and bg < 0:
            needed = -bg + 0.05 * lam
        else:
            needed = 0.05 * lam

        inc = int(np.ceil(needed / lam))
        if inc < 1:
            inc = 1

        new_count = max(edge_n_used[u, v], edge_n_used[v, u]) + inc
        edge_n_used[u, v] = new_count
        edge_n_used[v, u] = new_count

    return edge_distance + lam * edge_n_used

