            best_pair_delta = np.inf
            best_new_edges = None

            for n1, n2 in [((a, c), (b, d)), ((a, d), (b, c))]:
                e1 = canon(n1[0], n1[1])
                e2 = canon(n2[0], n2[1])
                if e1 in tour_set or e2 in tour_set:
                    continue

                delta = (D[n1[0], n1[1]] + D[n2[0], n2[1]]
                         - D[a, b] - D[c, d])
                if delta < best_pair_delta:
                    best_pair_delta = delta
                    best_new_edges = (e1, e2)

            if best_new_edges is not None:
                if best_pair_delta < best_delta[i]:
                    best_delta[i] = best_pair_delta
                if best_pair_delta < best_delta[j]:
                    best_delta[j] = best_pair_delta

                w = 1.0 / (1.0 + max(0.0, best_pair_delta) / mean_dist)
                if best_pair_delta < 0:
                    w *= 1.0 + min(2.0, -best_pair_delta / mean_dist)

                for e in best_new_edges:
                    discount_scores[e] = discount_scores.get(e, 0.0) + w

    valid = best_delta[np.isfinite(best_delta)]
    if valid.size == 0:
        return D.copy()

    threshold = np.median(valid)
    penalty_factors = {}

    for i, (u, v) in enumerate(oriented_edges):
        if np.isfinite(best_delta[i]) and best_delta[i] <= threshold:
            e = canon(u, v)
            score = np.exp(-best_delta[i] / mean_dist)
            score = min(score, 3.0)

            usage = edge_n_used[u, v]
            usage_factor = 1.0 + 0.2 * np.log1p(usage)
            fac = alpha * score * usage_factor

            penalty_factors[e] = penalty_factors.get(e, 0.0) + fac

            edge_n_used[u, v] += 1
            edge_n_used[v, u] += 1

    discount_factors = {}
    if discount_scores:
        max_score = max(discount_scores.values())
        if max_score > 0:
            discount_factors = {
                e: beta * (s / max_score)
                for e, s in discount_scores.items()
            }

    updated = D.copy()

    for (u, v), fac in penalty_factors.items():
        fac = min(fac, 1.0)
        updated[u, v] *= (1.0 + fac)
        updated[v, u] *= (1.0 + fac)

    for (u, v), fac in discount_factors.items():
        fac = min(fac, 0.8)
        updated[u, v] *= max(0.1, 1.0 - fac)
        updated[v, u] *= max(0.1, 1.0 - fac)

    updated = (updated + updated.T) / 2.0
    return updated

import numpy as np

def update_edge_distance(edge_distance: np.ndarray, local_opt_tour: np.ndarray,
                         edge_n_used: np.ndarray) -> np.ndarray:
    D = np.asarray(edge_distance, dtype=float)
    n = D.shape[0]
    if n <= 3:
        return D.copy()

    tour = np.asarray(local_opt_tour, dtype=int).ravel()
    if tour.size != n or np.unique(tour).size != n or np.any(tour < 0) or np.any(tour >= n):
        return D.copy()

    nxt = np.empty(n, dtype=int)
    prv = np.empty(n, dtype=int)
    for k in range(n):
        i = int(tour[k])
        nxt[i] = int(tour[(k + 1) % n])
        prv[i] = int(tour[(k - 1) % n])

    usage = np.asarray(edge_n_used, dtype=float)
    if usage.shape != D.shape:
        usage = np.zeros_like(D)
    else:
        usage = np.maximum(usage, 0.0)

    triu = np.triu_indices(n, 1)
    mean_d = float(np.mean(D[triu])) if len(triu[0]) > 0 else 1.0
    if mean_d <= 0:
        mean_d = 1.0

    beta = 0.2 * mean_d
    K = max(1, int(np.ceil(n / 3.0)))

    candidates = []
    for i in range(n):
        ni = nxt[i]
        pi = prv[i]
        for j in range(i + 1, n):
            if j == ni or j == pi:
                continue
            nj = nxt[j]
            pj = prv[j]
            g1 = D[i, ni] + D[j, nj] - D[i, j] - D[ni, nj]
            g2 = D[pi, i] + D[pj, j] - D[pi, pj] - D[i, j]
            if g1 >= g2:
                candidates.append((g1, i, j, 1))
            else:
                candidates.append((g2, i, j, 2))

    if not candidates:
        return D.copy()

    candidates.sort(key=lambda x: x[0], reverse=True)
    candidates = candidates[:K]

    delta = np.zeros_like(D)

    def add_delta(a, b, val):
        if a == b:
            return
        w = 1.0 / (1.0 + max(usage[a, b], usage[b, a]))
        delta[a, b] += val * w
        delta[b, a] += val * w

    for idx, (g, i, j, orient) in enumerate(candidates):
        amount = beta * (1.0 - 0.5 * idx / max(1, len(candidates)))
        if orient == 1:
            rem1 = (i, nxt[i])
            rem2 = (j, nxt[j])
            add1 = (i, j)
            add2 = (nxt[i], nxt[j])
        else:
            rem1 = (prv[i], i)
            rem2 = (prv[j], j)
            add1 = (prv[i], prv[j])
            add2 = (i, j)

        for a, b in (rem1, rem2):
            add_delta(a, b, amount)
        for a, b in (add1, add2):
            add_delta(a, b, -amount)

    updated = D + delta
    np.maximum(updated, 0.0, out=updated)
    updated = 0.5 * (updated + updated.T)
    return updated
